import math

def percentile(values, p):
    s = sorted(values)
    rank = max(1, math.ceil(p / 100 * len(s)))
    return s[rank - 1]

def summary(values):
    return {'p50': percentile(values, 50), 'p95': percentile(values, 95), 'p99': percentile(values, 99), 'mean': round(sum(values) / len(values), 1)}

import hashlib

def cache_key(tenant, model, prompt_version, question):
    q = ' '.join(question.split())
    raw = '\x1f'.join([tenant, model, prompt_version, q])
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()

