def monthly_cost(requests, in_tok, out_tok, small, large, escalation_rate):
    def per_call(prices):
        return (in_tok * prices[0] + out_tok * prices[1]) / 1_000_000
    total = requests * per_call(small) + requests * escalation_rate * per_call(large)
    return round(total, 2)
